// Figma: Loader page illustration animations (testTube, capsule, tablet, heartBeat, dotLoader, scanning, search,
// Liquid-loader-animation1/2/3, .dotsAnimation, .Spinner, atomsRotateAnimation, skeletonAnimation) and the
// "loaderAnimation" switcher. Every Figma variant is one frame; frames are generated by scripts/generate/pulse-loaders.mjs
// into loaders.generated.ts and cross-faded using the prototype hold/transition times.
import { forwardRef, useMemo } from 'react';
import Box from '@mui/material/Box';
import { keyframes } from '@mui/material/styles';
import type { SxProps, Theme } from '@mui/material/styles';
import { loaderAnimations } from './loaders.generated';
import type { LoaderAnimationData, LoaderAnimationKey } from './loaders.generated';

export type LoaderAnimationType =
  | 'scanning' | 'heart' | 'slidingDots' | 'search' | 'testTube' | 'capsule' | 'tablet'
  | 'liquid1' | 'liquid2' | 'liquid3' | 'dots' | 'spinner';

/** Figma loaderAnimation "Animation Type" order. "Liquid Loader" in that set is Liquid-loader-animation2. */
export const loaderAnimationTypes: LoaderAnimationType[] = [
  'scanning', 'heart', 'slidingDots', 'search', 'testTube', 'capsule', 'tablet', 'liquid2', 'dots', 'spinner',
];

const FADE_EPS = 0.0001;
const cache = new Map<string, ReturnType<typeof keyframes>[]>();

/** One opacity keyframes rule per frame: the frame is on during its hold, and cross-fades with its neighbours during tweens. */
function frameKeyframes(key: string, data: LoaderAnimationData) {
  const hit = cache.get(key);
  if (hit) return hit;
  const f = data.frames;
  const n = f.length;
  const dur = f.map((x) => Math.max(x.hold + x.tween, FADE_EPS));
  const total = dur.reduce((a, b) => a + b, 0);
  const start: number[] = [];
  dur.reduce((acc, d, i) => ((start[i] = acc), acc + d), 0);
  const pct = (t: number) => `${Math.max(0, Math.min(100, (t / total) * 100)).toFixed(4)}%`;
  const out = f.map((fr, i) => {
    const a = start[i] ?? 0;
    const prev = f[(i - 1 + n) % n];
    const tin = prev?.tween ?? 0;
    const holdEnd = a + Math.max(fr.hold, FADE_EPS);
    const end = a + (dur[i] ?? 0);
    const stops: [number, number][] = [];
    if (i === 0) {
      stops.push([0, 1], [holdEnd, 1], [end, 0], [Math.max(total - tin, end + FADE_EPS), 0], [total, 1]);
    } else {
      stops.push([0, 0], [Math.max(a - tin, 0), 0], [a, 1], [holdEnd, 1], [end, 0], [total, 0]);
    }
    // monotonic, de-duplicated percentages
    let last = -1;
    const rules = stops
      .map(([t, v]) => [Math.max(t, last), v] as const)
      .map(([t, v]) => ((last = t), `${pct(t)} { opacity: ${v}; }`))
      .join('\n');
    return keyframes(rules);
  });
  cache.set(key, out);
  return out;
}

export interface IllustrationLoaderProps {
  /** Which animation. */
  type: LoaderAnimationType;
  /** Show one fixed frame (0-based index, a Figma variant) instead of looping. */
  frame?: number;
  /** Rendered width in px (height follows the artwork's aspect ratio). Defaults to the Figma size. */
  size?: number;
  /** Accessible name. @default "Loading" */
  'aria-label'?: string;
  sx?: SxProps<Theme>;
}

function Frames({ k, data, size, label, sx, frame }: { k: string; data: LoaderAnimationData; size?: number; label: string; sx?: SxProps<Theme>; frame?: number }) {
  const anims = useMemo(() => (data.animated && frame === undefined ? frameKeyframes(k, data) : []), [k, data, frame]);
  const total = data.frames.reduce((a, f) => a + Math.max(f.hold + f.tween, FADE_EPS), 0);
  const w = size ?? data.width;
  const h = (w * data.height) / data.width;
  return (
    <Box
      component="svg"
      role="progressbar"
      aria-label={label}
      viewBox={`0 0 ${data.width} ${data.height}`}
      width={w}
      height={h}
      data-spec={`loader ${k}`}
      sx={[{ display: 'block', flexShrink: 0, overflow: 'visible' }, ...(Array.isArray(sx) ? sx : sx ? [sx] : [])]}
    >
      <defs dangerouslySetInnerHTML={{ __html: data.frames.map((f) => f.defs).join('') }} />
      {data.frames.map((f, i) => (
        <Box
          key={f.name}
          component="g"
          data-frame={f.name}
          sx={{
            opacity: i === (frame ?? 0) ? 1 : 0,
            // Reduced motion: hold on the first frame.
            '@media (prefers-reduced-motion: no-preference)': anims[i] ? { animation: `${anims[i]} ${total}s linear infinite` } : undefined,
          }}
          dangerouslySetInnerHTML={{ __html: f.body }}
        />
      ))}
    </Box>
  );
}

/** Looping illustration loader. Pauses on its first frame when the user prefers reduced motion. */
export const IllustrationLoader = forwardRef<SVGSVGElement, IllustrationLoaderProps>(function IllustrationLoader(
  { type, frame, size, 'aria-label': label = 'Loading', sx },
  _ref,
) {
  return <Frames k={type} data={loaderAnimations[type]} size={size} label={label} sx={sx} frame={frame} />;
});
IllustrationLoader.displayName = 'IllustrationLoader';

const make = (type: LoaderAnimationType, name: string) => {
  const C = (props: Omit<IllustrationLoaderProps, 'type'>) => <IllustrationLoader type={type} {...props} />;
  C.displayName = name;
  return C;
};
export const TestTubeLoader = make('testTube', 'TestTubeLoader');
export const CapsuleLoader = make('capsule', 'CapsuleLoader');
export const TabletLoader = make('tablet', 'TabletLoader');
export const HeartBeatLoader = make('heart', 'HeartBeatLoader');
export const ScanningLoader = make('scanning', 'ScanningLoader');
export const SearchLoader = make('search', 'SearchLoader');
export const LiquidLoader1 = make('liquid1', 'LiquidLoader1');
export const LiquidLoader2 = make('liquid2', 'LiquidLoader2');
export const LiquidLoader3 = make('liquid3', 'LiquidLoader3');
export const FigmaDotsLoader = make('dots', 'FigmaDotsLoader');
export const FigmaSlidingDotsLoader = make('slidingDots', 'FigmaSlidingDotsLoader');
export const FigmaSpinner = make('spinner', 'FigmaSpinner');

export type { LoaderAnimationKey };
